insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$tower-of-london$dyk$), $dyk$Legend says the kingdom will fall if the Tower's six ravens ever fly away – so their wings are clipped and a dedicated 'Ravenmaster' cares for them daily.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$tower-of-london$dyk$), $dyk$In the 13th century a polar bear lived at the Tower – it was allowed to swim and fish in the Thames on a leash.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$tower-of-london$dyk$), $dyk$The Crown Jewels kept here include Cullinan I, one of the largest cut diamonds in the world at 530 carats.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$tower-of-london$dyk$), $dyk$The Ceremony of the Keys has taken place every night for over 700 years – it was once delayed by a bomb during the Blitz, but still went ahead.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$tower-bridge$dyk$), $dyk$In 1952, bus driver Albert Gunter had to accelerate and 'jump' his double-decker across the gap when the bridge suddenly began to open beneath him – he made it, and received a £10 reward.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$tower-bridge$dyk$), $dyk$In 1968 a Hawker Hunter fighter jet illegally flew BETWEEN the bridge's towers in protest – the pilot was arrested after landing.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$tower-bridge$dyk$), $dyk$The bridge still opens around 800 times a year, and ships always have priority over cars.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$tower-bridge$dyk$), $dyk$The towers look like stone but are steel skeletons clad in granite and Portland stone.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$big-ben$dyk$), $dyk$The bell known as Big Ben has had a crack since 1859 – it's what gives the chime its distinctive tone.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$big-ben$dyk$), $dyk$The clock is fine-tuned with old penny coins placed on the pendulum: one coin changes the rate by 0.4 seconds per day.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$big-ben$dyk$), $dyk$The tower leans about 0.26 degrees to the north-west – visible to the naked eye if you look closely.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$big-ben$dyk$), $dyk$During the Second World War the clock kept chiming even as Parliament was bombed – the tower survived the Blitz.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$st-pauls-cathedral$dyk$), $dyk$No building in London was permitted to stand taller than St Paul's dome until 1963.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$st-pauls-cathedral$dyk$), $dyk$In the Whispering Gallery, a whisper against the wall can be heard 30 metres away on the opposite side.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$st-pauls-cathedral$dyk$), $dyk$During the Blitz, volunteer fire watchers slept on the cathedral roof to extinguish incendiary bombs.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$st-pauls-cathedral$dyk$), $dyk$Wren's tombstone bears the inscription 'Si monumentum requiris, circumspice' – 'If you seek his monument, look around you.'$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$rosetta-stone-british-museum$dyk$), $dyk$The same text appears three times on the stone: in hieroglyphs, Demotic script and Greek.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$rosetta-stone-british-museum$dyk$), $dyk$The French found the stone in 1799 – but the British took it as spoils of war after Napoleon's defeat.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$rosetta-stone-british-museum$dyk$), $dyk$Champollion reportedly cried 'Je tiens l'affaire!' ('I've got it!') and fainted when he cracked the code in 1822.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$rosetta-stone-british-museum$dyk$), $dyk$The Rosetta Stone is the British Museum's most visited object – the museum welcomes over six million visitors a year.$dyk$, 3),
  ((select id from public.hotspots where slug = $dyk$rosetta-stone-british-museum$dyk$), $dyk$During the First World War the stone was hidden in an Underground station to protect it from bombs.$dyk$, 4);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$nelsons-column$dyk$), $dyk$Nelson had already lost an eye and an arm in earlier battles when he died at Trafalgar in 1805.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$nelsons-column$dyk$), $dyk$Sculptor Edwin Landseer used a dead lion from London Zoo as his model – it began to decompose before he finished.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$nelsons-column$dyk$), $dyk$The lions' backs are anatomically wrong – concave like a dog's rather than straight.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$nelsons-column$dyk$), $dyk$Hitler reportedly planned to dismantle the column and move it to Berlin after a successful invasion.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$st-jamess-park$dyk$), $dyk$Pelicans have lived in the park since 1664 – a gift from the Russian ambassador.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$st-jamess-park$dyk$), $dyk$One of the park's pelicans became notorious in 2006 when it swallowed a live pigeon in front of shocked tourists.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$st-jamess-park$dyk$), $dyk$James I kept crocodiles and camels here in the 17th century.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$st-jamess-park$dyk$), $dyk$The park is surrounded by three palaces – Buckingham Palace, St James's Palace and Westminster.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$tate-modern$dyk$), $dyk$Architect Giles Gilbert Scott designed both the power station and Britain's classic red telephone box.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$tate-modern$dyk$), $dyk$The Turbine Hall is 35 metres high – Olafur Eliasson's artificial sun here drew over two million visitors in 2003.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$tate-modern$dyk$), $dyk$The chimney was deliberately built lower than the dome of St Paul's across the river – out of respect.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$tate-modern$dyk$), $dyk$Entry to the collections is free, as at most major museums in London.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$covent-garden$dyk$), $dyk$Samuel Pepys watched England's first recorded Punch and Judy show here in 1662.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$covent-garden$dyk$), $dyk$Street performers must pass an audition to perform on the piazza.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$covent-garden$dyk$), $dyk$The name comes from 'convent garden' – Westminster Abbey's kitchen garden stood here in the Middle Ages.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$covent-garden$dyk$), $dyk$My Fair Lady's Eliza Doolittle was a flower girl right here at Covent Garden market.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$abbey-road-crossing$dyk$), $dyk$The entire photo shoot took ten minutes – the photographer stood on a stepladder while a policeman stopped the traffic.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$abbey-road-crossing$dyk$), $dyk$Paul McCartney is barefoot on the cover – which fuelled the myth that he had secretly died.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$abbey-road-crossing$dyk$), $dyk$The crossing was granted Grade II listed heritage status in 2010.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$abbey-road-crossing$dyk$), $dyk$The wall outside the studio is repainted regularly – it constantly fills up with fans' graffiti.$dyk$, 3),
  ((select id from public.hotspots where slug = $dyk$abbey-road-crossing$dyk$), $dyk$A webcam streams the crossing live around the clock – wave to the world!$dyk$, 4);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$platform-nine-and-three-quarters$dyk$), $dyk$Rowling has admitted she mixed up King's Cross with Euston – the wall she described doesn't actually exist here.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$platform-nine-and-three-quarters$dyk$), $dyk$The film scenes were shot at platforms 4 and 5, not 9 and 10.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$platform-nine-and-three-quarters$dyk$), $dyk$Half a luggage trolley is mounted in the wall – as if it's on its way to Hogwarts.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$platform-nine-and-three-quarters$dyk$), $dyk$Rowling's parents met on a train departing from King's Cross station.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$trafalgar-square-police-box$dyk$), $dyk$The station held a single police officer – and in emergencies, two very cramped prisoners.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$trafalgar-square-police-box$dyk$), $dyk$When the telephone receiver was lifted, the lamp on top flashed to summon backup.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$trafalgar-square-police-box$dyk$), $dyk$Today it serves as a broom cupboard for Westminster Council cleaners.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$trafalgar-square-police-box$dyk$), $dyk$It was built in 1926 to discreetly monitor demonstrations on the square – the public had objected to a visible police box.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$london-stone$dyk$), $dyk$According to legend, London falls if the stone is destroyed: 'So long as the Stone of Brutus is safe, so long shall London flourish.'$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$london-stone$dyk$), $dyk$Rebel leader Jack Cade struck the stone with his sword in 1450 and declared himself lord of London – the scene appears in Shakespeare.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$london-stone$dyk$), $dyk$Nobody knows what the stone originally was – a Roman milestone, a druidic altar and a magical guardian stone have all been proposed.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$london-stone$dyk$), $dyk$The stone has survived both the Great Fire of 1666 and the bombing raids of the Second World War.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$fifty-berkeley-square$dyk$), $dyk$Prime Minister George Canning lived in the house until his death in 1827.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$fifty-berkeley-square$dyk$), $dyk$In the 1887 legend, two sailors spent the night in the attic room – one fled, the other was found dead on the railings outside.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$fifty-berkeley-square$dyk$), $dyk$The ghost is said to appear as a brown mist that frightens onlookers out of their wits.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$fifty-berkeley-square$dyk$), $dyk$The recluse Thomas Myers, who lived here alone in the 1860s, is thought to have sparked the ghost rumours.$dyk$, 3),
  ((select id from public.hotspots where slug = $dyk$fifty-berkeley-square$dyk$), $dyk$No hauntings have been reported since a bookshop took over the house in the 1930s.$dyk$, 4);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$sweeney-todd-fleet-street$dyk$), $dyk$Sweeney Todd probably never existed – the story comes from the serial 'The String of Pearls', published 1846–47.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$sweeney-todd-fleet-street$dyk$), $dyk$According to legend, the victims became the filling in Mrs Lovett's popular meat pies.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$sweeney-todd-fleet-street$dyk$), $dyk$The barber's chair stood over a trapdoor – one flick of a lever and the customer plunged into the cellar.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$sweeney-todd-fleet-street$dyk$), $dyk$The legend became both a Sondheim musical (1979) and a Tim Burton film starring Johnny Depp (2007).$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$eiffel-tower$dyk$), $dyk$The tower was only meant to stand for 20 years – a radio antenna saved it from demolition.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$eiffel-tower$dyk$), $dyk$It grows up to 15 centimetres taller on hot summer days due to thermal expansion.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$eiffel-tower$dyk$), $dyk$Gustave Eiffel kept a small private apartment near the top, where he received Thomas Edison.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$eiffel-tower$dyk$), $dyk$A con artist named Victor Lustig 'sold' the tower for scrap metal to a dealer in 1925 – twice.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$notre-dame-cathedral$dyk$), $dyk$Victor Hugo wrote The Hunchback of Notre-Dame partly as a campaign to save the neglected cathedral.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$notre-dame-cathedral$dyk$), $dyk$Napoleon crowned himself Emperor here in 1804 – taking the crown from the Pope's own hands.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$notre-dame-cathedral$dyk$), $dyk$The 2019 fire destroyed the roof, but the 8,000-pipe great organ survived.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$notre-dame-cathedral$dyk$), $dyk$Around 2,000 craftspeople, using medieval techniques, rebuilt the cathedral for its 2024 reopening.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$mona-lisa-louvre$dyk$), $dyk$The 1911 theft by handyman Vincenzo Peruggia made the painting world-famous – the empty wall drew huge crowds.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$mona-lisa-louvre$dyk$), $dyk$Pablo Picasso was briefly questioned as a suspect in the theft.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$mona-lisa-louvre$dyk$), $dyk$The painting is smaller than most visitors expect: just 77 by 53 centimetres.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$mona-lisa-louvre$dyk$), $dyk$She has no clearly visible eyebrows – possibly lost through early restoration attempts.$dyk$, 3),
  ((select id from public.hotspots where slug = $dyk$mona-lisa-louvre$dyk$), $dyk$The Mona Lisa has her own postbox at the Louvre for the love letters she receives.$dyk$, 4);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$arc-de-triomphe$dyk$), $dyk$Aviator Charles Godefroy flew a biplane through the arch in 1919 – the gap is less than 15 metres wide.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$arc-de-triomphe$dyk$), $dyk$The eternal flame beneath the arch has been rekindled every evening since 1923 without exception.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$arc-de-triomphe$dyk$), $dyk$Napoleon never saw his arch completed – he passed beneath it only as a coffin in 1840.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$arc-de-triomphe$dyk$), $dyk$Twelve avenues meet here, making the surrounding roundabout one of the most chaotic in Europe – insurance companies famously split the blame 50/50.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$sainte-chapelle$dyk$), $dyk$The Crown of Thorns relic cost King Louis IX more than the entire chapel built to house it.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$sainte-chapelle$dyk$), $dyk$Two-thirds of the stained glass is original 13th-century work – 1,113 biblical scenes in total.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$sainte-chapelle$dyk$), $dyk$The chapel was built in about seven years – astonishingly fast for the Middle Ages.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$sainte-chapelle$dyk$), $dyk$During the Revolution it served as a filing archive, which accidentally protected the glass.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$napoleons-tomb-invalides$dyk$), $dyk$Napoleon lies inside six nested coffins: tin, mahogany, two of lead, ebony and oak.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$napoleons-tomb-invalides$dyk$), $dyk$The open crypt forces visitors to bow their heads to see the tomb – by design, many claim.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$napoleons-tomb-invalides$dyk$), $dyk$A million Parisians watched his remains return from Saint Helena in December 1840.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$napoleons-tomb-invalides$dyk$), $dyk$Les Invalides still functions partly as a home for wounded French veterans, as Louis XIV intended.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$jardin-du-luxembourg$dyk$), $dyk$The wooden toy sailboats on the pond have been rented out to children since the 1920s.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$jardin-du-luxembourg$dyk$), $dyk$Hemingway claimed he caught pigeons here for dinner when he was a broke young writer.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$jardin-du-luxembourg$dyk$), $dyk$The garden's beehives have produced honey since 1856 – it's sold at an annual harvest festival.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$jardin-du-luxembourg$dyk$), $dyk$One of the original small-scale models of the Statue of Liberty stands among the trees.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$musee-dorsay$dyk$), $dyk$The building was a working railway station from 1900 to 1939.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$musee-dorsay$dyk$), $dyk$Orson Welles filmed his adaptation of Kafka's The Trial in the abandoned station in 1962.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$musee-dorsay$dyk$), $dyk$You can look out over Paris through the giant transparent clock face on the upper floor.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$musee-dorsay$dyk$), $dyk$It holds the world's largest collection of Impressionist and Post-Impressionist masterpieces.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$place-du-tertre$dyk$), $dyk$Around 140 licensed artists share the numbered pitches on the square, many working alternate days.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$place-du-tertre$dyk$), $dyk$Picasso painted Les Demoiselles d'Avignon nearby in 1907 – the birth of Cubism.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$place-du-tertre$dyk$), $dyk$Montmartre still has its own working vineyard, Clos Montmartre, harvested every autumn.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$place-du-tertre$dyk$), $dyk$The word 'bistro' is said to come from Russian soldiers occupying Montmartre in 1814, shouting 'bystro!' ('quickly!') at waiters – a charming story, though linguists doubt it.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$point-zero$dyk$), $dyk$Every road distance sign pointing to Paris in France measures to this exact spot.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$point-zero$dyk$), $dyk$Standing on the marker and spinning is said to guarantee you'll return to Paris.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$point-zero$dyk$), $dyk$Beneath the square lies an archaeological crypt with ruins of the original Roman-era city.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$point-zero$dyk$), $dyk$The marker was temporarily removed during the post-fire restoration works and later returned.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$nicolas-flamel-house$dyk$), $dyk$Built in 1407, it is the oldest stone house still standing in Paris.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$nicolas-flamel-house$dyk$), $dyk$The real Flamel was a wealthy scribe and philanthropist – the alchemy legends appeared 200 years after his death.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$nicolas-flamel-house$dyk$), $dyk$Lodgers stayed free in the house if they promised to pray for the dead.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$nicolas-flamel-house$dyk$), $dyk$J.K. Rowling borrowed Flamel for Harry Potter – in the books he is over 600 years old.$dyk$, 3),
  ((select id from public.hotspots where slug = $dyk$nicolas-flamel-house$dyk$), $dyk$Treasure hunters once smashed his tombstone hunting for hidden alchemical gold.$dyk$, 4);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$pont-des-arts$dyk$), $dyk$At its peak the bridge carried around 700,000 love locks weighing some 45 tonnes.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$pont-des-arts$dyk$), $dyk$A railing section collapsed under the weight of the locks in 2014.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$pont-des-arts$dyk$), $dyk$The keys thrown into the Seine posed a genuine problem for the riverbed.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$pont-des-arts$dyk$), $dyk$It was the first iron bridge in Paris, opened in 1804 under Napoleon.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$palais-garnier-phantom$dyk$), $dyk$The 'underground lake' exists – a vast cistern beneath the building, used by firefighters for diving practice.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$palais-garnier-phantom$dyk$), $dyk$In 1896 a falling chandelier counterweight really did kill an audience member, inspiring the novel's famous scene.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$palais-garnier-phantom$dyk$), $dyk$Box Five still carries a plaque marking it as the Phantom's private box.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$palais-garnier-phantom$dyk$), $dyk$The building has a beehive-dotted roof – its honey is sold in luxury shops.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$catacombs-of-paris$dyk$), $dyk$The bones of some six million Parisians are stacked in the tunnels.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$catacombs-of-paris$dyk$), $dyk$The entrance bears the warning: 'Stop! This is the empire of death.'$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$catacombs-of-paris$dyk$), $dyk$Police found an illegal fully equipped cinema and bar hidden in the tunnel network in 2004.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$catacombs-of-paris$dyk$), $dyk$The tunnels are former limestone quarries – the stone of Paris itself was mined here.$dyk$, 3),
  ((select id from public.hotspots where slug = $dyk$catacombs-of-paris$dyk$), $dyk$Illegal explorers of the 300-kilometre network are known as 'cataphiles'.$dyk$, 4);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$pere-lachaise-jim-morrison$dyk$), $dyk$The cemetery boosted its popularity in 1817 by relocating Molière and the lovers Héloïse and Abélard here.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$pere-lachaise-jim-morrison$dyk$), $dyk$Chopin's heart was removed and smuggled to Warsaw – his body remains here.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$pere-lachaise-jim-morrison$dyk$), $dyk$Oscar Wilde's tomb needed a glass screen to protect it from thousands of lipstick kisses.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$pere-lachaise-jim-morrison$dyk$), $dyk$Jim Morrison's grave is the most visited – conspiracy theories still claim he faked his death.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$colosseum$dyk$), $dyk$The arena could be flooded for staged naval battles in its early years.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$colosseum$dyk$), $dyk$Twenty-eight elevators beneath the floor made wild animals 'appear' in the arena.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$colosseum$dyk$), $dyk$The 80 numbered entrances could empty all 50,000 seats in minutes – modern stadiums copy the design.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$colosseum$dyk$), $dyk$Gladiators were costly stars who rarely fought to the death – some had sponsorship deals.$dyk$, 3),
  ((select id from public.hotspots where slug = $dyk$colosseum$dyk$), $dyk$Its marble cladding was stripped over centuries to build Renaissance Rome, including St Peter's.$dyk$, 4);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$pantheon$dyk$), $dyk$The dome is still the largest unreinforced concrete dome in the world after 1,900 years.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$pantheon$dyk$), $dyk$Rain falls through the open oculus – the ancient floor has 22 working drainage holes.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$pantheon$dyk$), $dyk$The painter Raphael is buried inside, at his own request.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$pantheon$dyk$), $dyk$On Pentecost, firefighters climb to the roof and drop thousands of rose petals through the oculus.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$roman-forum$dyk$), $dyk$Julius Caesar was cremated here – flowers are still laid on the altar of his temple.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$roman-forum$dyk$), $dyk$A Vestal Virgin who let Rome's sacred flame go out was flogged; breaking her vow of chastity meant burial alive.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$roman-forum$dyk$), $dyk$After Rome's fall the Forum lay buried under 12 metres of earth and was used as a cow pasture.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$roman-forum$dyk$), $dyk$The word 'forum' gave us words like 'forensic' – court proceedings happened here.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$st-peters-basilica$dyk$), $dyk$Floor markers show where other famous cathedrals would end if placed inside the basilica.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$st-peters-basilica$dyk$), $dyk$Michelangelo signed his Pietà after hearing it attributed to a rival – then regretted it and never signed again.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$st-peters-basilica$dyk$), $dyk$Selling indulgences to fund the construction helped spark the Protestant Reformation.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$st-peters-basilica$dyk$), $dyk$Excavations beneath the altar in the 1940s uncovered a first-century tomb, traditionally Peter's.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$sistine-chapel$dyk$), $dyk$Michelangelo considered himself a sculptor and initially refused the commission.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$sistine-chapel$dyk$), $dyk$God's and Adam's fingers do not actually touch – the tiny gap is the painting's genius.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$sistine-chapel$dyk$), $dyk$A painter nicknamed 'the breeches-maker' was hired to cover the nudes after Michelangelo's death.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$sistine-chapel$dyk$), $dyk$Papal elections are held here – white smoke from the chimney announces a new pope.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$caesar-assassination-site$dyk$), $dyk$Caesar was stabbed 23 times – but a physician concluded only one wound was fatal.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$caesar-assassination-site$dyk$), $dyk$'Et tu, Brute?' comes from Shakespeare – ancient sources report different last words, or none.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$caesar-assassination-site$dyk$), $dyk$He fell at the foot of a statue of Pompey, his defeated arch-rival.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$caesar-assassination-site$dyk$), $dyk$The murder aimed to save the Republic – instead it produced the Roman Empire.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$villa-borghese$dyk$), $dyk$The park hosts a working 19th-century water clock, powered entirely by flowing water since 1867.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$villa-borghese$dyk$), $dyk$Cardinal Borghese sometimes jailed artists who refused to sell him their works.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$villa-borghese$dyk$), $dyk$The Pincio terrace offers Rome's most famous sunset view over St Peter's dome.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$villa-borghese$dyk$), $dyk$The park contains a full replica of Shakespeare's Globe Theatre, built in 2003.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$piazza-navona$dyk$), $dyk$The square preserves the exact oval of Domitian's ancient athletics stadium beneath it.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$piazza-navona$dyk$), $dyk$In summers past, the piazza was deliberately flooded for aristocratic carriage parades.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$piazza-navona$dyk$), $dyk$The tale that Bernini's river god shields his eyes from rival Borromini's church is a myth – the timing doesn't work.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$piazza-navona$dyk$), $dyk$An ancient Egyptian-style obelisk, actually carved in Rome, crowns the fountain.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$galleria-borghese$dyk$), $dyk$The marble leaves in Apollo and Daphne are so thin they resonate when lightly tapped.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$galleria-borghese$dyk$), $dyk$Bernini carved his David's face while studying himself in a mirror held by a cardinal.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$galleria-borghese$dyk$), $dyk$Caravaggio painted his own face onto Goliath's severed head as a plea for a papal pardon.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$galleria-borghese$dyk$), $dyk$Entry works on strict two-hour slots with limited numbers – booking ahead is essential.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$trevi-fountain$dyk$), $dyk$Around 1.5 million euros in coins are tossed in yearly – all donated to charity.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$trevi-fountain$dyk$), $dyk$The fountain is fed by an aqueduct built in 19 BC that still works.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$trevi-fountain$dyk$), $dyk$Anita Ekberg's midnight wade in La Dolce Vita (1960) made the fountain world-famous.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$trevi-fountain$dyk$), $dyk$Wading in the fountain today brings a fine of several hundred euros.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$aventine-keyhole$dyk$), $dyk$The view lines up three sovereign territories: Malta's priory, Italy, and the Vatican.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$aventine-keyhole$dyk$), $dyk$The Knights of Malta issue their own passports and licence plates despite having no country.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$aventine-keyhole$dyk$), $dyk$No one knows for certain whether the keyhole view was designed deliberately.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$aventine-keyhole$dyk$), $dyk$The square outside was designed by Piranesi – famous for engraving imaginary prisons.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$torre-argentina-cat-sanctuary$dyk$), $dyk$Rome's street cats are legally protected as 'bio-cultural heritage' with the right to stay where born.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$torre-argentina-cat-sanctuary$dyk$), $dyk$The sanctuary shelters and rehomes hundreds of cats each year, run entirely by volunteers.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$torre-argentina-cat-sanctuary$dyk$), $dyk$Film star Anna Magnani was one of Rome's most famous 'gattare' – volunteer cat feeders.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$torre-argentina-cat-sanctuary$dyk$), $dyk$The cats lounge on the very ruins where Caesar was stabbed in 44 BC.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$mouth-of-truth$dyk$), $dyk$The 'mouth' is probably an ancient Roman drain cover turned medieval lie detector.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$mouth-of-truth$dyk$), $dyk$A medieval tale tells of an adulteress who tricked the mouth with a technically true oath.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$mouth-of-truth$dyk$), $dyk$Audrey Hepburn's scream in Roman Holiday was real – Gregory Peck improvised the hand-bite prank.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$mouth-of-truth$dyk$), $dyk$Medieval accounts hint that hidden scorpions or blades punished the 'guilty'.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$capitoline-wolf$dyk$), $dyk$Rome still celebrates its legendary founding date: 21 April 753 BC.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$capitoline-wolf$dyk$), $dyk$Radiocarbon tests in 2007 suggest the 'ancient' wolf may be a medieval casting – scholars still argue.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$capitoline-wolf$dyk$), $dyk$The twins were added in the Renaissance, some 2,000 years of story after the wolf.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$capitoline-wolf$dyk$), $dyk$In 2007 archaeologists announced a grotto under the Palatine that may be the legendary Lupercal cave.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$pasquino$dyk$), $dyk$The word 'pasquinade' – a satirical lampoon – comes from this statue.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$pasquino$dyk$), $dyk$A pope wanted Pasquino drowned in the Tiber; an adviser warned the statue would 'croak louder' from the water.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$pasquino$dyk$), $dyk$Rome had a whole network of 'talking statues' that answered each other's satires.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$pasquino$dyk$), $dyk$Romans still tape poems and protests to Pasquino's plinth today.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$sagrada-familia$dyk$), $dyk$Gaudí died in 1926 after a tram accident – mistaken for a beggar because of his shabby clothes.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$sagrada-familia$dyk$), $dyk$Construction has taken over 140 years and is funded entirely by donations and tickets.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$sagrada-familia$dyk$), $dyk$Gaudí designed the structure using upside-down models made of hanging chains and weights.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$sagrada-familia$dyk$), $dyk$A magic square on the Passion façade sums to 33 in every direction – the age of Christ.$dyk$, 3),
  ((select id from public.hotspots where slug = $dyk$sagrada-familia$dyk$), $dyk$When complete, its central tower will make it the tallest church in the world.$dyk$, 4);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$casa-batllo$dyk$), $dyk$Locals nicknamed it the House of Bones for its skeletal balconies and pillars.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$casa-batllo$dyk$), $dyk$The roof is widely read as the dragon slain by Saint George, Catalonia's patron saint.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$casa-batllo$dyk$), $dyk$The light well's tiles shift through five blues so all floors get equal light.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$casa-batllo$dyk$), $dyk$It stands on the 'Block of Discord', where rival architects built clashing masterpieces side by side.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$barcelona-cathedral$dyk$), $dyk$Thirteen white geese live in the cloister – one for each year of the martyred Santa Eulàlia's life.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$barcelona-cathedral$dyk$), $dyk$The 'medieval' façade was actually added in the 1880s, following a 1408 design.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$barcelona-cathedral$dyk$), $dyk$The geese historically served as an alarm system against intruders and thieves.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$barcelona-cathedral$dyk$), $dyk$At Corpus Christi an empty eggshell 'dances' on the cloister fountain – a tradition centuries old.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$santa-maria-del-mar$dyk$), $dyk$Port stevedores carried the stones on their backs from a quarry across the city – they're carved on the doors.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$santa-maria-del-mar$dyk$), $dyk$Built in just 54 years, giving it a stylistic purity almost unique among Gothic churches.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$santa-maria-del-mar$dyk$), $dyk$A 1936 fire burned inside for eleven days – paradoxically restoring the pure Gothic interior.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$santa-maria-del-mar$dyk$), $dyk$Ildefonso Falcones' novel 'Cathedral of the Sea' tells its construction story and sold millions.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$picasso-frieze-architects-college$dyk$), $dyk$Picasso never saw his largest public artwork – he refused to enter Franco's Spain.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$picasso-frieze-architects-college$dyk$), $dyk$Norwegian artist Carl Nesjar sandblasted Picasso's drawings into the concrete.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$picasso-frieze-architects-college$dyk$), $dyk$The nearby Picasso Museum opened in 1963 – the only museum created with Picasso's cooperation during his life.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$picasso-frieze-architects-college$dyk$), $dyk$Picasso spent his teenage years in Barcelona and always called it his true artistic home.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$columbus-monument$dyk$), $dyk$Columbus points east-southeast towards the Mediterranean – not towards America.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$columbus-monument$dyk$), $dyk$Barcelona received Columbus after his first voyage in 1493, hosted by Ferdinand and Isabella.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$columbus-monument$dyk$), $dyk$A tiny lift inside the column has carried visitors to the viewpoint since the 1920s.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$columbus-monument$dyk$), $dyk$The monument was built for the 1888 Universal Exposition that transformed the city.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$park-guell$dyk$), $dyk$The park was a failed housing development – only 2 of 60 planned villas were sold.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$park-guell$dyk$), $dyk$Gaudí himself lived in the show house for twenty years; it's now his museum.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$park-guell$dyk$), $dyk$The mosaic salamander on the stairway, 'el drac', is one of the world's most photographed lizards.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$park-guell$dyk$), $dyk$The serpentine bench's curve was allegedly moulded from a worker's imprint in wet plaster.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$la-boqueria$dyk$), $dyk$The market began with medieval traders dodging taxes just outside the old city gate.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$la-boqueria$dyk$), $dyk$Some 200 stalls operate under its Modernista stained-glass sign.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$la-boqueria$dyk$), $dyk$Top chefs shop here personally – the tiny market bars serve some of Spain's best simple food.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$la-boqueria$dyk$), $dyk$It stands on the site of a former convent, demolished in the 1830s.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$barceloneta-beach$dyk$), $dyk$The beaches are largely artificial – created for the 1992 Olympic Games.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$barceloneta-beach$dyk$), $dyk$Before 1992 the shore was industrial land; Barcelona 'lived with its back to the sea'.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$barceloneta-beach$dyk$), $dyk$Frank Gehry's giant golden fish sculpture presides over the beach's north end.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$barceloneta-beach$dyk$), $dyk$The Barceloneta quarter was built in the 1750s for families displaced by a military citadel.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$miro-mosaic-la-rambla$dyk$), $dyk$Miró made three welcome artworks: airport (air), port sculpture (sea), and this pavement (land).$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$miro-mosaic-la-rambla$dyk$), $dyk$One tile carries Miró's signature – finding it is a local pastime.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$miro-mosaic-la-rambla$dyk$), $dyk$The artist wanted people to walk on it: everyday art for everyday life.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$miro-mosaic-la-rambla$dyk$), $dyk$It marks the spot of a medieval city gate where travellers once entered Barcelona.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$font-de-canaletes$dyk$), $dyk$A plaque promises that whoever drinks here will return to Barcelona.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$font-de-canaletes$dyk$), $dyk$FC Barcelona fans have celebrated every major trophy at this fountain since the 1930s.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$font-de-canaletes$dyk$), $dyk$The tradition began when fans gathered here to read results outside a sports newspaper's office.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$font-de-canaletes$dyk$), $dyk$The water is ordinary city drinking water – the magic is strictly legendary.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$gaudi-lampposts-placa-reial$dyk$), $dyk$These lampposts from 1879 were Gaudí's first public commission, at around age 26.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$gaudi-lampposts-placa-reial$dyk$), $dyk$His school director said of him: 'Either a fool or a genius. Time will show.'$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$gaudi-lampposts-placa-reial$dyk$), $dyk$The lamps are crowned with Mercury's winged helmet – god of commerce.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$gaudi-lampposts-placa-reial$dyk$), $dyk$Gaudí never worked for the city again – all his famous works were private or church commissions.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$pont-del-bisbe$dyk$), $dyk$The 'medieval' bridge is from 1928 – younger than the telephone.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$pont-del-bisbe$dyk$), $dyk$A skull pierced by a dagger is carved on its underside.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$pont-del-bisbe$dyk$), $dyk$Legend says removing the dagger would make Barcelona fall.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$pont-del-bisbe$dyk$), $dyk$The architect allegedly added the skull as a curse after his grander plans were rejected.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$santa-eulalia-descent$dyk$), $dyk$Legend says Eulàlia was rolled down this exact street in a barrel full of knives.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$santa-eulalia-descent$dyk$), $dyk$She suffered thirteen tortures – one for each year of her life.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$santa-eulalia-descent$dyk$), $dyk$A sudden snowfall is said to have covered her body – snow in Barcelona remains nearly as miraculous.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$santa-eulalia-descent$dyk$), $dyk$The cathedral keeps thirteen geese in her honour to this day.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$placa-sant-felip-neri$dyk$), $dyk$The shrapnel scars from the 1938 bombing were deliberately left unrepaired.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$placa-sant-felip-neri$dyk$), $dyk$The long-repeated firing-squad story is false – a plaque now tells the true history.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$placa-sant-felip-neri$dyk$), $dyk$Gaudí was walking to daily mass at this church when he was fatally struck by a tram.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$placa-sant-felip-neri$dyk$), $dyk$The square sits over a medieval cemetery, and some surrounding buildings were moved here stone by stone.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$brandenburg-gate$dyk$), $dyk$Napoleon stole the rooftop Quadriga in 1806 and displayed it in Paris.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$brandenburg-gate$dyk$), $dyk$For 28 years the gate stood inside the Berlin Wall's death strip – reachable by no one.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$brandenburg-gate$dyk$), $dyk$Reagan's 'Tear down this wall!' speech was delivered here in 1987.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$brandenburg-gate$dyk$), $dyk$The gate was modelled on the entrance to the Acropolis in Athens.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$reichstag$dyk$), $dyk$Soviet soldiers' 1945 graffiti is preserved on the interior walls behind glass.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$reichstag$dyk$), $dyk$The 1933 fire enabled Hitler's seizure of emergency powers – the arsonist's identity is still debated.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$reichstag$dyk$), $dyk$Christo wrapped the entire building in silver fabric in 1995 – five million people visited.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$reichstag$dyk$), $dyk$The glass dome lets citizens walk literally above their parliamentarians at work.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$checkpoint-charlie$dyk$), $dyk$The name is simply 'C' in the NATO alphabet – after checkpoints Alpha and Bravo.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$checkpoint-charlie$dyk$), $dyk$American and Soviet tanks faced off here for 16 hours in 1961, loaded and 30 metres apart.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$checkpoint-charlie$dyk$), $dyk$Escapees hid in modified cars – one crossed in a car so low the guards' barrier passed over it.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$checkpoint-charlie$dyk$), $dyk$The original guardhouse stands in the Allied Museum; this one is a faithful replica.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$east-side-gallery$dyk$), $dyk$The famous Brezhnev–Honecker kiss painting is based on a real 1979 photograph.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$east-side-gallery$dyk$), $dyk$Painting this side of the Wall before 1989 was impossible – approaching it from the East meant risking death.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$east-side-gallery$dyk$), $dyk$118 artists from 21 countries painted the gallery in 1990.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$east-side-gallery$dyk$), $dyk$Souvenir hunters chipped so much of the Wall that the artworks needed full restoration.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$holocaust-memorial$dyk$), $dyk$The 2,711 concrete blocks have no official meaning – the architect refused all symbolism.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$holocaust-memorial$dyk$), $dyk$Reading aloud the names of all known victims would take over six years.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$holocaust-memorial$dyk$), $dyk$The memorial stands on the former death strip of the Berlin Wall.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$holocaust-memorial$dyk$), $dyk$An underground centre documents individual victims and family fates by name.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$frederick-the-great-statue$dyk$), $dyk$Visitors still lay potatoes on Frederick's grave – he forced the potato onto sceptical Germans.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$frederick-the-great-statue$dyk$), $dyk$East Germany exiled the statue in 1950, then reinstated it in 1980.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$frederick-the-great-statue$dyk$), $dyk$Frederick corresponded with Voltaire and composed over 100 flute sonatas.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$frederick-the-great-statue$dyk$), $dyk$Sculptor Christian Daniel Rauch placed thinkers beneath the horse's tail – allegedly with intent.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$tiergarten$dyk$), $dyk$Freezing Berliners felled almost every tree for firewood in the winters of 1945–46.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$tiergarten$dyk$), $dyk$The park's trees were replanted after 1949, many donated by other German cities.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$tiergarten$dyk$), $dyk$It began as a royal hunting ground in 1527 – 'Tiergarten' means animal garden.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$tiergarten$dyk$), $dyk$At 210 hectares it is larger than London's Hyde Park.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$museum-island$dyk$), $dyk$Nefertiti's 3,400-year-old bust still has one deliberately unfinished eye – no one knows why.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$museum-island$dyk$), $dyk$The Ishtar Gate of Babylon was rebuilt indoors from original glazed bricks.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$museum-island$dyk$), $dyk$The Neues Museum stood as a war ruin for 60 years; its restoration preserves the bullet scars.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$museum-island$dyk$), $dyk$The whole island is a UNESCO World Heritage Site – five museums built over a century.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$mauerpark-karaoke$dyk$), $dyk$The park occupies the Wall's former death strip – the name means 'Wall park'.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$mauerpark-karaoke$dyk$), $dyk$Bearpit Karaoke draws up to 2,000 spectators to a stone amphitheatre every Sunday in season.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$mauerpark-karaoke$dyk$), $dyk$It was started in 2009 by an Irish courier with speakers on a cargo bike.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$mauerpark-karaoke$dyk$), $dyk$A surviving Wall segment here is a legal graffiti zone, repainted daily.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$fernsehturm-popes-revenge$dyk$), $dyk$Sunlight on the sphere creates a glowing cross – 'the Pope's Revenge' over the atheist GDR.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$fernsehturm-popes-revenge$dyk$), $dyk$At 368 metres it is still the tallest structure in Germany.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$fernsehturm-popes-revenge$dyk$), $dyk$The restaurant sphere rotates – originally once per hour, now twice.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$fernsehturm-popes-revenge$dyk$), $dyk$Reagan cited the light-cross in his famous 1987 'Tear down this wall' speech.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$weltzeituhr$dyk$), $dyk$The clock shows the time in 148 cities – built for citizens forbidden to travel to them.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$weltzeituhr$dyk$), $dyk$Designer Erich John had nine months to create the ten-tonne machine.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$weltzeituhr$dyk$), $dyk$Protests in autumn 1989 gathered beneath it before the Wall fell.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$weltzeituhr$dyk$), $dyk$A planetary model rotates on top once per minute.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$jfk-ich-bin-ein-berliner$dyk$), $dyk$The 'jam doughnut' story is a myth invented decades later – his German was correct.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$jfk-ich-bin-ein-berliner$dyk$), $dyk$Half a million Berliners packed the square for the 1963 speech.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$jfk-ich-bin-ein-berliner$dyk$), $dyk$The square was renamed for Kennedy within days of his assassination.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$jfk-ich-bin-ein-berliner$dyk$), $dyk$The American-donated Freedom Bell in the tower rings every day at noon.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$teufelsberg$dyk$), $dyk$The hill is built from some 75 million cubic metres of WWII rubble – a bombed city, piled up.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$teufelsberg$dyk$), $dyk$An indestructible Nazi academy building lies buried inside the mountain.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$teufelsberg$dyk$), $dyk$The NSA's listening station on top eavesdropped deep into the Eastern Bloc.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$teufelsberg$dyk$), $dyk$Much of what the station actually intercepted remains classified.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$ghost-stations-nordbahnhof$dyk$), $dyk$Western trains rolled slowly through the sealed station for 28 years without stopping.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$ghost-stations-nordbahnhof$dyk$), $dyk$The armed East German guards inside were themselves locked in to prevent their escape.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$ghost-stations-nordbahnhof$dyk$), $dyk$Street entrances were bricked up – a generation walked over the station unaware.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$ghost-stations-nordbahnhof$dyk$), $dyk$When reopened in 1990, newspapers from 1961 still lay inside.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$fuehrerbunker-site$dyk$), $dyk$Hitler died here on 30 April 1945; the bunker lies crushed and buried below.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$fuehrerbunker-site$dyk$), $dyk$Berlin deliberately left the site unmarked until a single info board appeared in 2006.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$fuehrerbunker-site$dyk$), $dyk$The bodies were burned roughly where cars park today.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$fuehrerbunker-site$dyk$), $dyk$The Holocaust memorial stands a two-minute walk away – a deliberate contrast.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$anne-frank-house$dyk$), $dyk$The entrance to the annexe was hidden behind a swinging bookcase.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$anne-frank-house$dyk$), $dyk$Anne's diary has been translated into around 70 languages and sold over 30 million copies.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$anne-frank-house$dyk$), $dyk$Helper Miep Gies saved the diary without reading it – 'otherwise I would have had to burn it', she later said, since it named everyone.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$anne-frank-house$dyk$), $dyk$The identity of the betrayer has never been established.$dyk$, 3),
  ((select id from public.hotspots where slug = $dyk$anne-frank-house$dyk$), $dyk$Anne's film-star pictures still hang on her bedroom wall.$dyk$, 4);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$royal-palace-amsterdam$dyk$), $dyk$The palace rests on 13,659 wooden piles driven into the marshy soil.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$royal-palace-amsterdam$dyk$), $dyk$Built as a town hall, it was called the Eighth Wonder of the World.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$royal-palace-amsterdam$dyk$), $dyk$Floor maps in the great hall let citizens walk across the Dutch trading empire.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$royal-palace-amsterdam$dyk$), $dyk$Napoleon's brother turned it into a palace by moving in, in 1808.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$westerkerk$dyk$), $dyk$Rembrandt is buried somewhere under the church – in an unmarked rented grave never located.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$westerkerk$dyk$), $dyk$Anne Frank wrote lovingly about these bells, which she heard from her hiding place.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$westerkerk$dyk$), $dyk$The blue crown on the spire was a thank-you gift right from Emperor Maximilian I.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$westerkerk$dyk$), $dyk$At 85 metres it has been Amsterdam's tallest church tower since 1631.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$oude-kerk$dyk$), $dyk$The floor consists of about 2,500 gravestones covering some 10,000 burials.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$oude-kerk$dyk$), $dyk$Rembrandt's wife Saskia is buried here – he sold her grave when poverty struck.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$oude-kerk$dyk$), $dyk$Its wooden vault is the largest medieval wooden ceiling in Europe.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$oude-kerk$dyk$), $dyk$The city's oldest building now stands in the middle of the red light district.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$night-watch-rijksmuseum$dyk$), $dyk$The 'night' is dirty varnish – cleaning revealed it's a daylight scene.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$night-watch-rijksmuseum$dyk$), $dyk$The canvas was trimmed in 1715 to fit a wall, losing two figures permanently.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$night-watch-rijksmuseum$dyk$), $dyk$It has survived two knife attacks and one acid attack.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$night-watch-rijksmuseum$dyk$), $dyk$Missing edges are known thanks to a small 17th-century copy – and were digitally reconstructed with AI in 2021.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$rembrandt-house$dyk$), $dyk$Rembrandt painted The Night Watch while living here.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$rembrandt-house$dyk$), $dyk$His 1656 bankruptcy inventory of 363 items allowed the house's exact reconstruction.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$rembrandt-house$dyk$), $dyk$He collected everything: weapons, shells, stuffed animals, Roman busts.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$rembrandt-house$dyk$), $dyk$Daily demonstrations still run on an etching press like the master's own.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$vondelpark$dyk$), $dyk$In the early 1970s up to 100,000 young travellers per summer legally slept in the park.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$vondelpark$dyk$), $dyk$Picasso donated a five-metre sculpture for the park's 100th birthday in 1965.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$vondelpark$dyk$), $dyk$Built on soft peat, the park is perpetually, gently sinking.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$vondelpark$dyk$), $dyk$It draws around ten million visits a year.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$van-gogh-museum$dyk$), $dyk$Van Gogh sold barely any paintings in his lifetime – the recorded sale is 'The Red Vineyard'.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$van-gogh-museum$dyk$), $dyk$His sister-in-law Johanna built his fame by publishing his letters and organising exhibitions.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$van-gogh-museum$dyk$), $dyk$The museum holds over 200 paintings and 800 letters – the world's largest collection.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$van-gogh-museum$dyk$), $dyk$He painted around 900 works in just ten years – roughly two per week.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$bloemenmarkt$dyk$), $dyk$The stalls stand on houseboats – growers once sailed in and sold straight from the barge.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$bloemenmarkt$dyk$), $dyk$During 1630s tulip mania, one rare bulb could cost as much as a canal house.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$bloemenmarkt$dyk$), $dyk$The prized striped tulips owed their patterns to an unknown virus.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$bloemenmarkt$dyk$), $dyk$The bubble burst in February 1637 – history's most cited market crash.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$narrowest-house-amsterdam$dyk$), $dyk$The house is 2.02 metres wide – roughly the span of a door and its frame.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$narrowest-house-amsterdam$dyk$), $dyk$Amsterdam's houses grew narrow because tax was based on canal frontage width.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$narrowest-house-amsterdam$dyk$), $dyk$Furniture still enters most canal houses through the windows, via gable hoisting beams.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$narrowest-house-amsterdam$dyk$), $dyk$A rival 'narrowest house' was allegedly built as wide as a rich man's front door – for his coachman.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$de-poezenboot$dyk$), $dyk$It began in 1966 with one stray cat family under a tree – then word spread among cats.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$de-poezenboot$dyk$), $dyk$The floating shelter is a registered charity with its own adoption programme.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$de-poezenboot$dyk$), $dyk$Permanent residents are cats too wild or old to rehome – they get a canal view for life.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$de-poezenboot$dyk$), $dyk$It is widely considered the world's only floating cat sanctuary.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$dancing-houses-damrak$dyk$), $dyk$Many façades lean forward on purpose, so hoisted goods clear the front wall.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$dancing-houses-damrak$dyk$), $dyk$The houses stand on wooden piles – fine underwater, doomed if air reaches them.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$dancing-houses-damrak$dyk$), $dyk$Locals joke the city is 'built on herring bones'.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$dancing-houses-damrak$dyk$), $dyk$Uneven pile settling gives the Damrak row its famous 'dancing' look.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$begijnhof-grave-in-the-gutter$dyk$), $dyk$Beguine Cornelia Arens chose burial in the gutter over the chapel in 1654 – legend says her coffin moved itself there.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$begijnhof-grave-in-the-gutter$dyk$), $dyk$The courtyard's wooden Houten Huys (c. 1530) is Amsterdam's oldest surviving house.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$begijnhof-grave-in-the-gutter$dyk$), $dyk$A 'hidden church' operated here after Catholicism was banned in 1578.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$begijnhof-grave-in-the-gutter$dyk$), $dyk$The houses are still reserved exclusively for single women.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$house-with-the-heads$dyk$), $dyk$The six heads officially depict Roman gods – but legend says they honour a maid's sword work.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$house-with-the-heads$dyk$), $dyk$In the tale, she beheaded six burglars one by one through the cellar hatch.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$house-with-the-heads$dyk$), $dyk$The most romantic version has her marrying into the household as reward.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$house-with-the-heads$dyk$), $dyk$The house later held a famous collection of alchemical and mystical texts.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$miracle-of-amsterdam$dyk$), $dyk$The 1345 miracle turned a fishing town into a major pilgrimage city.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$miracle-of-amsterdam$dyk$), $dyk$The unburnt host 'returned' to the house by itself – twice, according to the legend.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$miracle-of-amsterdam$dyk$), $dyk$Thousands still walk the silent Stille Omgang procession every March at night.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$miracle-of-amsterdam$dyk$), $dyk$Pilgrim emperor Maximilian's gratitude gave Amsterdam the crown on its coat of arms and the Westerkerk spire.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$schoenbrunn-palace$dyk$), $dyk$Six-year-old Mozart allegedly proposed to Marie Antoinette here after his 1762 concert.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$schoenbrunn-palace$dyk$), $dyk$The palace has 1,441 rooms – the imperial family used around 40.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$schoenbrunn-palace$dyk$), $dyk$Schönbrunn's zoo, founded in 1752, is the oldest still operating in the world.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$schoenbrunn-palace$dyk$), $dyk$Emperor Franz Joseph was born and died in the palace, ruling 68 years in between.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$st-stephens-cathedral$dyk$), $dyk$The Pummerin bell was first cast from Turkish cannons captured in the 1683 siege.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$st-stephens-cathedral$dyk$), $dyk$Habsburg rulers' entrails rest in urns in the catacombs – hearts and bodies lie in other churches.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$st-stephens-cathedral$dyk$), $dyk$Fire watchmen lived in the tower's tip until 1955.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$st-stephens-cathedral$dyk$), $dyk$Austria welcomes each New Year to the toll of its bell, broadcast live nationwide.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$hofburg$dyk$), $dyk$The complex holds about 2,600 rooms across 18 wings built over six centuries.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$hofburg$dyk$), $dyk$The treasury keeps the Holy Roman Empire's thousand-year-old crown and the 'Holy Lance'.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$hofburg$dyk$), $dyk$White Lipizzaner stallions have danced at the Spanish Riding School since the 16th century.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$hofburg$dyk$), $dyk$Empress Sisi's private gym equipment survives in her apartments – she exercised obsessively.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$klimt-kiss-belvedere$dyk$), $dyk$Austria bought The Kiss before Klimt had even finished painting it.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$klimt-kiss-belvedere$dyk$), $dyk$The gold is genuine gold leaf – Klimt's father was a gold engraver.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$klimt-kiss-belvedere$dyk$), $dyk$The models are likely Klimt and his lifelong companion Emilie Flöge – he never confirmed it.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$klimt-kiss-belvedere$dyk$), $dyk$Klimt painted in a long blue smock, reportedly with nothing underneath, and fathered at least 14 children.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$mozarthaus$dyk$), $dyk$Mozart composed The Marriage of Figaro in this apartment.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$mozarthaus$dyk$), $dyk$He kept a pet starling that whistled his piano concerto theme – and held a funeral when it died.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$mozarthaus$dyk$), $dyk$Haydn told Mozart's father here that Wolfgang was 'the greatest composer known to me'.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$mozarthaus$dyk$), $dyk$It is the only one of Mozart's dozen Viennese apartments still standing.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$maria-theresa-monument$dyk$), $dyk$She ruled the empire for 40 years while bearing sixteen children.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$maria-theresa-monument$dyk$), $dyk$Her strategic marriages earned her the title 'mother-in-law of Europe'.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$maria-theresa-monument$dyk$), $dyk$Young Mozart appears among the figures at the monument's base.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$maria-theresa-monument$dyk$), $dyk$She won over Hungary's nobles by appearing before them holding her infant son.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$prater-riesenrad$dyk$), $dyk$Built in 1897, it is among the oldest Ferris wheels still turning.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$prater-riesenrad$dyk$), $dyk$Orson Welles delivered The Third Man's famous 'cuckoo clock' speech in one of its cabins.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$prater-riesenrad$dyk$), $dyk$It turns at 75 cm per second – slow enough to dine in the cabins, which you can book.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$prater-riesenrad$dyk$), $dyk$Half its cabins were lost in WWII and never replaced, giving it a distinctive gap-toothed look.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$johann-strauss-monument$dyk$), $dyk$Strauss's father violently opposed his career – the boy learned violin in secret.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$johann-strauss-monument$dyk$), $dyk$The Blue Danube functions as Austria's unofficial national anthem.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$johann-strauss-monument$dyk$), $dyk$He sometimes jotted melodies on his shirt cuffs mid-tour.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$johann-strauss-monument$dyk$), $dyk$The fully gilded statue is reputedly Vienna's most photographed monument.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$volksgarten$dyk$), $dyk$The park was planted over bastions Napoleon's troops blew up in 1809.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$volksgarten$dyk$), $dyk$Its Theseus Temple is a replica of the Athenian original.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$volksgarten$dyk$), $dyk$Over 3,000 labelled rose bushes bloom here – many carry sponsors' name plaques.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$volksgarten$dyk$), $dyk$A marble memorial mourns Empress Sisi, assassinated in 1898.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$hundertwasserhaus$dyk$), $dyk$Hundertwasser called the straight line 'godless' – the building barely has one.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$hundertwasserhaus$dyk$), $dyk$The floors inside deliberately undulate: 'a melody to the feet'.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$hundertwasserhaus$dyk$), $dyk$Residents were granted 'window rights' – legally allowed to repaint around their own windows.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$hundertwasserhaus$dyk$), $dyk$The artist took no fee, glad to have 'prevented something ugly' on the site.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$ankeruhr$dyk$), $dyk$All twelve historical figures parade at noon – a 15-minute show running since 1914.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$ankeruhr$dyk$), $dyk$The clock was built by an insurance company as a monumental advertisement.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$ankeruhr$dyk$), $dyk$Marcus Aurelius leads the parade – the Roman emperor died in ancient Vienna.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$ankeruhr$dyk$), $dyk$It stands on Vienna's oldest square, the forum of Roman Vindobona.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$kapuzinergruft-habsburg-hearts$dyk$), $dyk$Habsburgs were buried in three parts: body here, heart elsewhere, entrails in the cathedral.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$kapuzinergruft-habsburg-hearts$dyk$), $dyk$At the crypt door, each dead emperor is refused entry until announced as 'a sinful mortal'.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$kapuzinergruft-habsburg-hearts$dyk$), $dyk$The ritual was last performed for Otto von Habsburg in 2011.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$kapuzinergruft-habsburg-hearts$dyk$), $dyk$Maria Theresa's rococo sarcophagus shows her waking to face her husband for eternity.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$basilisk-schoenlaterngasse$dyk$), $dyk$The basilisk was said to hatch from a rooster's egg brooded by a toad.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$basilisk-schoenlaterngasse$dyk$), $dyk$A baker's apprentice defeated it with a mirror – it couldn't survive its own reflection.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$basilisk-schoenlaterngasse$dyk$), $dyk$A weathered stone in the house's niche is 'the petrified basilisk' to this day.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$basilisk-schoenlaterngasse$dyk$), $dyk$The legend is dated with medieval precision to the year 1212.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$stock-im-eisen$dyk$), $dyk$The tree was felled around 1440 – and people hammered nails into it for centuries.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$stock-im-eisen$dyk$), $dyk$Legend says the Devil forged its unpickable lock in exchange for an apprentice's soul.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$stock-im-eisen$dyk$), $dyk$Journeymen likely nailed iron in for luck when arriving in Vienna.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$stock-im-eisen$dyk$), $dyk$It survives in a glass case on the city's busiest shopping corner.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$der-liebe-augustin-griechenbeisl$dyk$), $dyk$Corpse collectors threw the drunk Augustin into a plague pit – he woke up fine and piped his way out.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$der-liebe-augustin-griechenbeisl$dyk$), $dyk$He survived the pit but died years later of drink, becoming Vienna's symbol of unkillable humour.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$der-liebe-augustin-griechenbeisl$dyk$), $dyk$The song 'O du lieber Augustin' still keeps his legend alive.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$der-liebe-augustin-griechenbeisl$dyk$), $dyk$The inn's guest signatures include Beethoven, Schubert and Mark Twain.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$charles-bridge$dyk$), $dyk$The foundation stone was laid at a palindromic moment: 1357 9/7 5:31.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$charles-bridge$dyk$), $dyk$Eggs really were used in the mortar – one village famously sent theirs hard-boiled.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$charles-bridge$dyk$), $dyk$It was Prague's only bridge for over 400 years.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$charles-bridge$dyk$), $dyk$Touching the bronze relief of St John of Nepomuk promises luck and a return to Prague.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$prague-castle$dyk$), $dyk$Guinness lists it as the largest ancient castle complex in the world.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$prague-castle$dyk$), $dyk$The crown jewels sit behind seven locks – seven officials each hold one key.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$prague-castle$dyk$), $dyk$The 1618 Defenestration of Prague – officials thrown from a window – started the Thirty Years' War.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$prague-castle$dyk$), $dyk$The victims survived the 17-metre fall, allegedly thanks to a dung heap.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$golden-lane$dyk$), $dyk$Kafka wrote in the little blue house No. 22 in 1916–17.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$golden-lane$dyk$), $dyk$The name comes from goldsmiths – the alchemist story is legend, though Rudolf II employed plenty.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$golden-lane$dyk$), $dyk$The tiny houses were built into the castle wall arches for Rudolf's guards.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$golden-lane$dyk$), $dyk$People lived in the lane until the Second World War.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$tyn-church$dyk$), $dyk$The two towers are deliberately unequal in width – romantics call them 'Adam and Eve'.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$tyn-church$dyk$), $dyk$The Hussites' golden chalice on the gable was melted into a Madonna's halo by the victors.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$tyn-church$dyk$), $dyk$Astronomer Tycho Brahe, buried inside, wore a metal nose after losing his in a duel over maths.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$tyn-church$dyk$), $dyk$Legend says Brahe died of a burst bladder at a banquet; tests point to kidney failure.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$prague-astronomical-clock$dyk$), $dyk$Running since 1410, it is the world's oldest astronomical clock still in operation.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$prague-astronomical-clock$dyk$), $dyk$Legend says the clockmaker was blinded so he could never build a better one – and stopped the clock in revenge.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$prague-astronomical-clock$dyk$), $dyk$A skeleton figure of Death rings the bell to start each hour's show.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$prague-astronomical-clock$dyk$), $dyk$Nearly destroyed by shelling in 1945, it was restored and running again by 1948.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$jan-hus-memorial$dyk$), $dyk$Hus was burned in 1415 – a century before Luther – despite an imperial safe conduct.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$jan-hus-memorial$dyk$), $dyk$His followers' peasant armies repeatedly defeated crusader knights.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$jan-hus-memorial$dyk$), $dyk$'Hus' means goose – he allegedly prophesied an unburnable swan would follow.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$jan-hus-memorial$dyk$), $dyk$The memorial became a site of silent protest under successive occupations.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$petrin-hill$dyk$), $dyk$Couples kiss under the cherry blossoms here every 1 May for a year of love.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$petrin-hill$dyk$), $dyk$The 'Hunger Wall' was built partly as medieval poverty relief.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$petrin-hill$dyk$), $dyk$The lookout tower is a mini Eiffel – its tip stands higher above sea level than the original's.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$petrin-hill$dyk$), $dyk$The funicular railway has run since 1891.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$lennon-wall$dyk$), $dyk$Communist police whitewashed the wall repeatedly – it repainted itself overnight every time.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$lennon-wall$dyk$), $dyk$Regime files labelled the youths who gathered here 'Lennonists'.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$lennon-wall$dyk$), $dyk$In 2014 art students whitewashed it entirely, leaving only 'Wall Is Over'.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$lennon-wall$dyk$), $dyk$The wall belongs to the Knights of Malta, who tolerate the endless repainting.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$u-fleku-brewery$dyk$), $dyk$Beer has been brewed here continuously since 1499.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$u-fleku-brewery$dyk$), $dyk$Its dark lager is served only on the premises – never bottled or exported.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$u-fleku-brewery$dyk$), $dyk$The halls seat around 1,200 drinkers in eight historic rooms.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$u-fleku-brewery$dyk$), $dyk$Waiters famously bring unordered refills and Becherovka – declining is a Prague survival skill.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$kafka-rotating-head$dyk$), $dyk$The head weighs 39 tonnes and moves in 42 independently rotating layers.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$kafka-rotating-head$dyk$), $dyk$Sculptor David Černý also made babies with barcode faces that climb Prague's TV tower.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$kafka-rotating-head$dyk$), $dyk$Kafka worked as an insurance clerk a few streets away.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$kafka-rotating-head$dyk$), $dyk$The face aligns completely only for moments – then dissolves again.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$dancing-house$dyk$), $dyk$Its towers are nicknamed Fred and Ginger after the dancing film stars.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$dancing-house$dyk$), $dyk$The site was bombed in 1945 by American planes that likely mistook Prague for Dresden.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$dancing-house$dyk$), $dyk$President Havel grew up next door and championed the project.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$dancing-house$dyk$), $dyk$Critics first called it a crushed cola can – now it's on the postcards.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$narrowest-street-certovka$dyk$), $dyk$The street is about 70 centimetres wide – with real traffic lights at each end.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$narrowest-street-certovka$dyk$), $dyk$It leads to the Devil's Stream, allegedly named after a notoriously sharp-tongued local woman.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$narrowest-street-certovka$dyk$), $dyk$The gap was originally a medieval firebreak between houses.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$narrowest-street-certovka$dyk$), $dyk$Locals dispute whether the lights are safety equipment or restaurant marketing.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$golem-old-new-synagogue$dyk$), $dyk$The Golem of clay allegedly lies in the synagogue's attic, awaiting reactivation.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$golem-old-new-synagogue$dyk$), $dyk$Rabbi Loew was a real, renowned 16th-century scholar – the Golem grew around his legend.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$golem-old-new-synagogue$dyk$), $dyk$The attic was long forbidden, its access ladder deliberately cut short.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$golem-old-new-synagogue$dyk$), $dyk$Visitors still leave written wishes at Rabbi Loew's grave nearby.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$faust-house$dyk$), $dyk$Real residents included an earless alchemist and a chemist whose experiments terrified Prague.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$faust-house$dyk$), $dyk$Legend says the Devil dragged Faust through the ceiling, leaving an uncloseable hole.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$faust-house$dyk$), $dyk$A lodger who accepted the Devil's daily coins allegedly vanished the same way.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$faust-house$dyk$), $dyk$Today the house belongs to a medical faculty – with a pharmacy at street level.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$vysehrad-libuse$dyk$), $dyk$Princess Libuše prophesied from this rock: 'a great city whose glory will touch the stars'.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$vysehrad-libuse$dyk$), $dyk$Prague ('Praha') is named, in legend, after a carved threshold – 'práh'.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$vysehrad-libuse$dyk$), $dyk$Composers Smetana and Dvořák lie in the national cemetery here.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$vysehrad-libuse$dyk$), $dyk$A cliff ruin called Libuše's Bath allegedly served for dropping discarded lovers into the Vltava.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$belem-tower$dyk$), $dyk$A carved rhinoceros on a turret is Europe's first stone portrait of the animal – from a real 1515 diplomatic gift.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$belem-tower$dyk$), $dyk$That rhino drowned in a shipwreck while being sent onward to the Pope.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$belem-tower$dyk$), $dyk$The unique 'Manueline' style covers the fortress in carved ropes and knots.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$belem-tower$dyk$), $dyk$Its tidal dungeon cells flooded with the river – prisoners tracked the tide by their ankles.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$jeronimos-monastery$dyk$), $dyk$Construction was funded by the 'pepper penny' – a tax on the spice trade.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$jeronimos-monastery$dyk$), $dyk$Vasco da Gama prayed here the night before sailing to India in 1497; his tomb is inside.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$jeronimos-monastery$dyk$), $dyk$The carved vault survived the 1755 earthquake that flattened central Lisbon.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$jeronimos-monastery$dyk$), $dyk$The monastery's monks are credited with the original pastel de nata recipe.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$sao-jorge-castle$dyk$), $dyk$The knight Martim Moniz allegedly jammed a closing gate open with his own body in 1147.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$sao-jorge-castle$dyk$), $dyk$The core walls are Moorish – Lisbon was an Islamic city for four centuries.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$sao-jorge-castle$dyk$), $dyk$Vasco da Gama was received here in triumph after reaching India.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$sao-jorge-castle$dyk$), $dyk$Peacocks now patrol the ramparts above the city.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$se-cathedral$dyk$), $dyk$Begun in 1147 on the site of the city's main mosque, the year Lisbon was conquered.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$se-cathedral$dyk$), $dyk$Its fortress-like design helped it survive the 1755 earthquake.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$se-cathedral$dyk$), $dyk$Saint Anthony 'of Padua' was baptised here – Lisbon insists he's Saint Anthony of Lisbon.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$se-cathedral$dyk$), $dyk$Excavations in the cloister descend through Moorish, Roman and Phoenician layers.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$monument-to-the-discoveries$dyk$), $dyk$Henry the Navigator, who leads the stone crew, never personally sailed on the great voyages.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$monument-to-the-discoveries$dyk$), $dyk$Thirty-three figures crowd the 'caravel', including one woman – Henry's English mother.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$monument-to-the-discoveries$dyk$), $dyk$A giant wind-rose map in the plaza was a gift from South Africa in 1960.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$monument-to-the-discoveries$dyk$), $dyk$The monument began as a temporary 1940 exhibition structure, rebuilt in stone in 1960.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$pessoa-statue-a-brasileira$dyk$), $dyk$Pessoa invented over 70 'heteronyms' – complete alternative poets who argued with each other in print.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$pessoa-statue-a-brasileira$dyk$), $dyk$He died nearly unknown, leaving a trunk of 25,000 unpublished pages.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$pessoa-statue-a-brasileira$dyk$), $dyk$His masterpiece 'The Book of Disquiet' was first published 47 years after his death.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$pessoa-statue-a-brasileira$dyk$), $dyk$The empty chair beside his statue is one of Lisbon's favourite photo spots.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$miradouro-senhora-do-monte$dyk$), $dyk$It is the highest of Lisbon's famous miradouro viewpoints.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$miradouro-senhora-do-monte$dyk$), $dyk$Pregnant women, including queens, traditionally prayed at the chapel's stone chair for safe births.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$miradouro-senhora-do-monte$dyk$), $dyk$The red 25 de Abril bridge below shares engineering lineage with the Golden Gate.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$miradouro-senhora-do-monte$dyk$), $dyk$Locals consider it the city's best sunset – and quietly resent its fame.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$azulejo-museum$dyk$), $dyk$A 23-metre panorama of about 1,300 tiles shows Lisbon as it looked before the 1755 earthquake destroyed it.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$azulejo-museum$dyk$), $dyk$The word azulejo comes from Arabic for 'polished stone'.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$azulejo-museum$dyk$), $dyk$Lisbon still commissions tile art – the metro stations are a living gallery.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$azulejo-museum$dyk$), $dyk$The museum occupies a convent founded in 1509 by a queen of Portugal.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$time-out-market$dyk$), $dyk$It was the world's first food hall curated by magazine critics – only reviewed favourites get a stall.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$time-out-market$dyk$), $dyk$Michelin-starred chefs serve counter food next to legendary tascas.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$time-out-market$dyk$), $dyk$The concept born here has been exported to New York, Miami, Dubai and more.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$time-out-market$dyk$), $dyk$The historic market next door has traded continuously since 1892.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$santa-justa-lift$dyk$), $dyk$The legend that its engineer studied under Eiffel is unconfirmed – but never dies.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$santa-justa-lift$dyk$), $dyk$It ran on steam power until 1907; the original electric machinery still works.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$santa-justa-lift$dyk$), $dyk$The wooden cabins carry about 20 passengers up 45 metres of cast iron.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$santa-justa-lift$dyk$), $dyk$It is classified as a national monument – a working one.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$pasteis-de-belem$dyk$), $dyk$The recipe came from monks of the Jerónimos Monastery after the monasteries closed in 1834.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$pasteis-de-belem$dyk$), $dyk$Only a handful of people know the full recipe – mixed in a locked 'Secret Workshop'.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$pasteis-de-belem$dyk$), $dyk$Only this bakery may call its tarts Pastéis de Belém; all others are 'de nata'.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$pasteis-de-belem$dyk$), $dyk$Tens of thousands of tarts leave the ovens here every day.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$tram-28-martim-moniz$dyk$), $dyk$The 1930s wooden trams survive because modern trams can't physically fit the old town's curves.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$tram-28-martim-moniz$dyk$), $dyk$In the narrowest lanes, clearance to the house walls is a matter of centimetres.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$tram-28-martim-moniz$dyk$), $dyk$Drivers operate a manual crank handbrake on the steep descents.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$tram-28-martim-moniz$dyk$), $dyk$It's affectionately known as the world's most scenic pickpocketing venue – guard your pockets.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$ravens-of-st-vincent$dyk$), $dyk$Two ravens allegedly escorted the saint's relics by boat to Lisbon in 1173.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$ravens-of-st-vincent$dyk$), $dyk$The ship-and-ravens image remains Lisbon's coat of arms on every lamppost and manhole.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$ravens-of-st-vincent$dyk$), $dyk$Ravens really were kept at the cathedral for centuries in the legend's honour.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$ravens-of-st-vincent$dyk$), $dyk$The church's rooftop terrace overlooks Alfama – and holds the royal Braganza pantheon.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$sao-domingos-church$dyk$), $dyk$The 1506 massacre began here – up to 2,000 'New Christians' were killed in three days.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$sao-domingos-church$dyk$), $dyk$The Inquisition read its sentences in this church.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$sao-domingos-church$dyk$), $dyk$Earthquake (1755) and fire (1959) both gutted it – the burn scars were deliberately left visible.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$sao-domingos-church$dyk$), $dyk$A memorial to the massacre victims was finally erected outside in 2008.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$severa-mouraria-fado$dyk$), $dyk$Fado's first star, Maria Severa, sang in this lane and died at 26 in 1846.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$severa-mouraria-fado$dyk$), $dyk$Her affair with a count gave fado its founding legend of impossible love.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$severa-mouraria-fado$dyk$), $dyk$Female fadistas still wear the black shawl in her memory.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$severa-mouraria-fado$dyk$), $dyk$No recording or photograph of her exists – the myth filled the silence.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$acropolis-parthenon$dyk$), $dyk$The Parthenon has almost no straight lines – curves and leaning columns correct optical illusions.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$acropolis-parthenon$dyk$), $dyk$It survived intact until 1687, when a Venetian shell hit an Ottoman gunpowder store inside.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$acropolis-parthenon$dyk$), $dyk$A 12-metre gold-and-ivory statue of Athena once stood within.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$acropolis-parthenon$dyk$), $dyk$Greece still campaigns for the return of the sculptures removed by Lord Elgin's agents.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$erechtheion-caryatids$dyk$), $dyk$The maidens' thick marble braids are secretly structural, strengthening their necks.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$erechtheion-caryatids$dyk$), $dyk$Five originals are in the Acropolis Museum – the sixth is in London.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$erechtheion-caryatids$dyk$), $dyk$Legend says the sisters weep at night for their stolen sixth.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$erechtheion-caryatids$dyk$), $dyk$Her place in the museum is deliberately left empty.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$temple-of-hephaestus$dyk$), $dyk$It is the most complete ancient Greek temple surviving anywhere.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$temple-of-hephaestus$dyk$), $dyk$Conversion into a church around the 7th century kept it roofed and maintained.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$temple-of-hephaestus$dyk$), $dyk$The surrounding district housed ancient metalworkers – fitting for the smith-god's temple.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$temple-of-hephaestus$dyk$), $dyk$Greece's first modern king was officially welcomed here in 1834.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$temple-of-olympian-zeus$dyk$), $dyk$Construction took nearly 650 years, from c. 520 BC to AD 131.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$temple-of-olympian-zeus$dyk$), $dyk$Athenians left it unfinished for centuries as a warning against megalomania.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$temple-of-olympian-zeus$dyk$), $dyk$One column, toppled by an 1852 storm, still lies in sliced marble drums.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$temple-of-olympian-zeus$dyk$), $dyk$Hadrian's Arch beside it declares two cities: Theseus's on one face, Hadrian's on the other.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$panathenaic-stadium$dyk$), $dyk$It is the world's only stadium built entirely of marble.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$panathenaic-stadium$dyk$), $dyk$The 1896 marathon winner Spyridon Louis became a Greek idiom for running off quickly.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$panathenaic-stadium$dyk$), $dyk$An ancient stadium has occupied the site since about 330 BC.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$panathenaic-stadium$dyk$), $dyk$Every Olympic flame is formally handed over to host nations here.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$academy-of-athens-statues$dyk$), $dyk$Plato's school in the grove of Akademos named every 'academy' since.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$academy-of-athens-statues$dyk$), $dyk$Socrates called himself a gadfly sent to sting the lazy horse of Athens – Athens chose hemlock.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$academy-of-athens-statues$dyk$), $dyk$The building is painted and gilded as ancient temples genuinely were.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$academy-of-athens-statues$dyk$), $dyk$It forms a neoclassical trilogy with the university and national library beside it.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$national-garden$dyk$), $dyk$Queen Amalia personally directed the planting and allegedly used navy ships for specimens.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$national-garden$dyk$), $dyk$The towering palms at the entrance descend from her original imports.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$national-garden$dyk$), $dyk$Roman mosaics and ancient column stumps sit casually among the flowerbeds.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$national-garden$dyk$), $dyk$Locals prize it as reliably cooler than the surrounding city in summer.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$acropolis-museum$dyk$), $dyk$The top gallery is rotated to align exactly with the Parthenon outside its windows.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$acropolis-museum$dyk$), $dyk$White plaster gaps in the frieze mark the pieces held in London – a deliberate argument.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$acropolis-museum$dyk$), $dyk$Glass floors reveal an entire excavated ancient neighbourhood beneath the building.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$acropolis-museum$dyk$), $dyk$The archaic statues still show traces of their original bright paint.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$anafiotika-plaka$dyk$), $dyk$Builders from the island of Anafi built it in the 1840s – allegedly overnight, exploiting a roof-by-dawn custom.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$anafiotika-plaka$dyk$), $dyk$Its lanes are too narrow for vehicles; deliveries finish by hand.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$anafiotika-plaka$dyk$), $dyk$Around forty whitewashed island houses survive, still inhabited.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$anafiotika-plaka$dyk$), $dyk$It sits directly beneath the Acropolis walls – a Cycladic village in the capital.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$evzones-syntagma$dyk$), $dyk$The kilt has 400 pleats – one per year of Ottoman rule, tradition holds.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$evzones-syntagma$dyk$), $dyk$Each red clog is studded with dozens of nails and crowned with a black pom-pom.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$evzones-syntagma$dyk$), $dyk$Guards stand perfectly motionless for hour-long shifts.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$evzones-syntagma$dyk$), $dyk$The grand changing ceremony with full parade happens Sundays at 11.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$syntagma-metro-museum$dyk$), $dyk$Metro construction became the largest archaeological dig in Athens' history – some 50,000 finds.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$syntagma-metro-museum$dyk$), $dyk$A glass wall in the station preserves the excavation strata century by century.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$syntagma-metro-museum$dyk$), $dyk$Monastiraki station displays an ancient riverbed beneath a glass floor.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$syntagma-metro-museum$dyk$), $dyk$Every metro extension in Athens doubles as a new dig.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$tower-of-the-winds$dyk$), $dyk$It combined sundials, a water clock and a weathervane – an ancient all-in-one instrument.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$tower-of-the-winds$dyk$), $dyk$Eight wind gods fly across its faces, one per compass point.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$tower-of-the-winds$dyk$), $dyk$Whirling dervishes used it for ceremonies in Ottoman times.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$tower-of-the-winds$dyk$), $dyk$The surrounding district is still called 'Aerides' – the Winds – after it.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$areopagus-hill$dyk$), $dyk$Legend makes it the site of the first murder trial – the god Ares before an Olympian jury.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$areopagus-hill$dyk$), $dyk$In Aeschylus's Oresteia, Athena's vote here ends the cycle of blood vengeance with law.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$areopagus-hill$dyk$), $dyk$The Apostle Paul preached his 'unknown god' sermon on this rock around AD 51.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$areopagus-hill$dyk$), $dyk$Millennia of visitors have polished the marble dangerously smooth – mind your step.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$lycabettus-hill$dyk$), $dyk$Legend says Athena dropped the rock in shock while carrying it to enlarge the Acropolis.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$lycabettus-hill$dyk$), $dyk$She allegedly turned crows black as punishment for the bad news.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$lycabettus-hill$dyk$), $dyk$The name likely means 'hill of wolves' – they roamed it into historical times.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$lycabettus-hill$dyk$), $dyk$Its summit chapel of St George stands higher than the Acropolis itself.$dyk$, 3);
insert into public.hotspot_facts (hotspot_id, text, sort_order) values
  ((select id from public.hotspots where slug = $dyk$socrates-prison$dyk$), $dyk$The 'prison' is almost certainly an ancient house – the real prison lay in the Agora.$dyk$, 0),
  ((select id from public.hotspots where slug = $dyk$socrates-prison$dyk$), $dyk$Excavators of the true prison found small clay cups – possibly for measured hemlock doses.$dyk$, 1),
  ((select id from public.hotspots where slug = $dyk$socrates-prison$dyk$), $dyk$National treasures were hidden in this cave from occupying forces in WWII.$dyk$, 2),
  ((select id from public.hotspots where slug = $dyk$socrates-prison$dyk$), $dyk$Socrates refused an arranged escape, choosing the hemlock at 70.$dyk$, 3);
